window.VO = [{"id":"n01","text":"You're a detective. One woman's DNA has turned up at forty crime scenes.","at":0.24,"t0":0.12,"t1":4.705},{"id":"n02","text":"Three countries. Sixteen years. They call her the woman without a face.","at":10.11,"t0":5.055,"t1":9.21},{"id":"n03","text":"Here's where her DNA turned up.","at":19.62,"t0":9.81,"t1":11.545},{"id":"n04b","text":"A murder in nineteen ninety-three.","at":23.89,"t0":11.945,"t1":13.705},{"id":"n05","text":"A cookie, at a break-in.","at":28.31,"t0":14.155,"t1":15.675},{"id":"n06","text":"A toy pistol, after a robbery in France.","at":32.25,"t0":16.125,"t1":18.77},{"id":"n07","text":"A heroin syringe. A stolen car.","at":38.44,"t0":19.22,"t1":21.51},{"id":"n08","text":"And in two thousand seven, the murder of a police officer.","at":44.02,"t0":22.01,"t1":25.39},{"id":"n09","text":"So who is she?","at":52.38,"t0":26.19,"t1":27.175},{"id":"n10","text":"A serial killer? A petty thief? Or more than one person?","at":54.95,"t0":27.475,"t1":30.805},{"id":"n11","text":"Police believed she was both. A brutal killer, and a common thief.","at":66.01,"t0":33.005,"t1":36.88},{"id":"n12","text":"But the people who saw her?","at":75.16,"t0":37.58,"t1":38.955},{"id":"n13","text":"Some said she looked like a man.","at":79.71,"t0":39.855,"t1":41.555}];
